"use client";

import { forwardRef, useEffect, useState, type HTMLAttributes } from "react";
import { avatarDefaults, type AvatarSpecProps } from "../generated/avatar.types";
import { cx } from "../utils/cx";

export interface AvatarProps
  extends AvatarSpecProps,
    Omit<HTMLAttributes<HTMLSpanElement>, keyof AvatarSpecProps | "className"> {
  className?: string;
}

const sizes: Record<NonNullable<AvatarSpecProps["size"]>, string> = {
  xs: "size-6 text-[10px]",
  sm: "size-8 text-xs",
  md: "size-10 text-sm",
  lg: "size-14 text-base",
};

/** "Ada Lovelace" -> "AL", "Ada" -> "A". Works on whole characters, so emoji and non-Latin names don't split. */
export function initialsOf(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return "";
  const first = Array.from(words[0])[0] ?? "";
  const last = words.length > 1 ? (Array.from(words[words.length - 1])[0] ?? "") : "";
  return (first + last).toLocaleUpperCase();
}

export const Avatar = forwardRef<HTMLSpanElement, AvatarProps>(function Avatar(
  {
    name,
    src,
    size = avatarDefaults.size,
    shape = avatarDefaults.shape,
    decorative = avatarDefaults.decorative,
    className,
    ...rest
  },
  ref,
) {
  const [failed, setFailed] = useState(false);
  useEffect(() => setFailed(false), [src]); // a new image gets a new chance
  const showImage = !!src && !failed;
  return (
    <span
      {...rest}
      ref={ref}
      // The image carries its own alt text; initials are text drawn as a picture.
      role={showImage || decorative ? undefined : "img"}
      aria-label={showImage || decorative ? undefined : name}
      aria-hidden={decorative || undefined}
      className={cx(
        "inline-flex shrink-0 select-none items-center justify-center overflow-hidden border border-[var(--rd-color-border-default)] " +
          "bg-[var(--rd-color-surface-subtle)] font-medium text-[var(--rd-color-text-default)]",
        shape === "circle" ? "rounded-full" : "rounded-[var(--rd-radius-control)]",
        sizes[size],
        className,
      )}
    >
      {showImage ? (
        <img src={src} alt={decorative ? "" : name} onError={() => setFailed(true)} className="size-full object-cover" />
      ) : (
        <span aria-hidden="true">{initialsOf(name)}</span>
      )}
    </span>
  );
});

// Generated by rdloom codegen from specs/avatar.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const avatarSizeValues = ["xs", "sm", "md", "lg"] as const;
export const avatarShapeValues = ["circle", "square"] as const;

/** A person's or account's picture, falling back to their initials when there is no image or it fails to load. */
export interface AvatarSpecProps {
  /**
   * The person's name. It is the accessible name, and the source of the initials.
   */
  name: string;
  /**
   * Image URL. If it is missing or fails to load, the initials show instead.
   */
  src?: string;
  /**
   * 24, 32, 40 or 56 px.
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg";
  /**
   * Circle for people, square for organisations.
   * @default "circle"
   */
  shape?: "circle" | "square";
  /**
   * Hides it from screen readers, for when the name is already written next to it.
   * @default false
   */
  decorative?: boolean;
}

export const avatarDefaults = {
  size: "md",
  shape: "circle",
  decorative: false,
} as const;

export const avatarMeta = {
  "name": "Avatar",
  "version": "0.1.0",
  "status": "experimental",
  "role": "img"
} as const;

