import { Table, TableBody, TableCell, TableColumn, TableHeader, TableRow } from "@rdloom/react";

const people = [
  { id: "ada", name: "Ada Lovelace", role: "Mathematician", city: "London" },
  { id: "grace", name: "Grace Hopper", role: "Rear admiral", city: "New York" },
  { id: "katherine", name: "Katherine Johnson", role: "Mathematician", city: "Hampton" },
];

// isRowHeader marks the column that names each row, so a screen reader can say
// "Grace Hopper, Role, Rear admiral" for a cell.
export default function TableBasicExample() {
  return (
    <div className="w-[34rem] max-w-full">
      <Table label="People">
        <TableHeader>
          <TableColumn isRowHeader>Name</TableColumn>
          <TableColumn>Role</TableColumn>
          <TableColumn>City</TableColumn>
        </TableHeader>
        <TableBody>
          {people.map((p) => (
            <TableRow key={p.id} id={p.id}>
              <TableCell>{p.name}</TableCell>
              <TableCell>{p.role}</TableCell>
              <TableCell>{p.city}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

import { useMemo, useState } from "react";
import { Table, TableBody, TableCell, TableColumn, TableHeader, TableRow, type SortDescriptor } from "@rdloom/react";

const invoices = [
  { id: "inv-1042", customer: "Acme", amount: 1200 },
  { id: "inv-1043", customer: "Globex", amount: 340 },
  { id: "inv-1044", customer: "Initech", amount: 980 },
  { id: "inv-1045", customer: "Hooli", amount: 15 },
];

// The table reports the sort; you sort your data and pass it back.
export default function TableSortableExample() {
  const [sort, setSort] = useState<SortDescriptor>({ column: "amount", direction: "descending" });
  const rows = useMemo(() => {
    const key = sort.column as "customer" | "amount";
    const sorted = [...invoices].sort((a, b) => (a[key] < b[key] ? -1 : a[key] > b[key] ? 1 : 0));
    return sort.direction === "descending" ? sorted.reverse() : sorted;
  }, [sort]);
  return (
    <div className="w-[28rem] max-w-full">
      <Table label="Invoices" sortDescriptor={sort} onSortChange={setSort}>
        <TableHeader>
          <TableColumn id="customer" isRowHeader allowsSorting>
            Customer
          </TableColumn>
          <TableColumn id="amount" allowsSorting>
            Amount
          </TableColumn>
        </TableHeader>
        <TableBody>
          {rows.map((r) => (
            <TableRow key={r.id} id={r.id}>
              <TableCell>{r.customer}</TableCell>
              <TableCell>${r.amount.toLocaleString("en-US")}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

import { useState } from "react";
import { Table, TableBody, TableCell, TableColumn, TableHeader, TableRow } from "@rdloom/react";

const files = [
  { id: "a", name: "report.pdf", size: "1.2 MB" },
  { id: "b", name: "photo.png", size: "840 KB" },
  { id: "c", name: "notes.txt", size: "4 KB" },
];

export default function TableSelectableExample() {
  const [selected, setSelected] = useState<"all" | Set<unknown>>(new Set(["b"]));
  const count = selected === "all" ? files.length : selected.size;
  return (
    <div className="flex w-[28rem] max-w-full flex-col gap-2 text-sm">
      <Table label="Files" selectionMode="multiple" selectedKeys={selected as Set<string>} onSelectionChange={(keys) => setSelected(keys)}>
        <TableHeader>
          <TableColumn isRowHeader>Name</TableColumn>
          <TableColumn>Size</TableColumn>
        </TableHeader>
        <TableBody>
          {files.map((f) => (
            <TableRow key={f.id} id={f.id}>
