export const timeFieldGranularityValues = ["hour", "minute", "second"] as const;
export const timeFieldSizeValues = ["sm", "md", "lg"] as const;

/** A field for a time of day, with separate hour, minute and (optional) second segments that follow the visitor's locale and 12 or 24 hour clock. */
export interface TimeFieldSpecProps {
  /**
   * Visible label, also the accessible name.
   */
  label: string;
  /**
   * Help text under the field.
   */
  description?: string;
  /**
   * Shown when the value is invalid. Leave out to use the built-in message.
   */
  errorMessage?: string;
  /**
   * Controlled value.
   */
  value?: import("react-aria-components").TimeValue | null;
  /**
   * Initial value when uncontrolled.
   */
  defaultValue?: import("react-aria-components").TimeValue | null;
  /**
   * Called with the time, or null when it is cleared.
   */
  onChange?: (value: import("react-aria-components").TimeValue | null) => void;
  /**
   * Smallest unit shown and edited.
   * @default "minute"
   */
  granularity?: "hour" | "minute" | "second";
  /**
   * Force a 12 or 24 hour clock. Leave out to follow the locale.
   */
  hourCycle?: 12 | 24;
  /**
   * Earliest allowed time.
   */
  minValue?: import("react-aria-components").TimeValue;
  /**
   * Latest allowed time.
   */
  maxValue?: import("react-aria-components").TimeValue;
  /**
   * Field height and text size.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Prevents interaction and dims the field.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Marks the field invalid. Leave undefined to let validation decide.
   */
  isInvalid?: boolean;
  /**
   * Marks the field required and adds an asterisk.
   * @default false
   */
  isRequired?: boolean;
}

export const timeFieldDefaults = {
