import type { ReactNode } from "react";

export const treeSelectionModeValues = ["none", "single", "multiple"] as const;

/** An expandable hierarchy such as folders and files or a nested menu, with keyboard navigation and optional selection. Build it from nested TreeItem elements. */
export interface TreeSpecProps {
  /**
   * Accessible name of the tree, e.g. "Files".
   */
  label: string;
  /**
   * TreeItem elements. Nest TreeItems inside a TreeItem to make children.
   */
  children: ReactNode;
  /**
   * Whether items can be selected.
   * @default "none"
   */
  selectionMode?: "none" | "single" | "multiple";
  /**
   * Controlled selection, by item id.
   */
  selectedKeys?: "all" | Iterable<import("react-aria-components").Key>;
  /**
   * Initial selection when uncontrolled.
   */
  defaultSelectedKeys?: "all" | Iterable<import("react-aria-components").Key>;
  /**
   * Called with the selected item ids.
   */
  onSelectionChange?: (keys: "all" | Set<import("react-aria-components").Key>) => void;
  /**
   * Controlled set of expanded items, by id.
   */
  expandedKeys?: Iterable<import("react-aria-components").Key>;
  /**
   * Items expanded at first.
   */
  defaultExpandedKeys?: Iterable<import("react-aria-components").Key>;
  /**
   * Called when items are expanded or collapsed.
   */
  onExpandedChange?: (keys: Set<import("react-aria-components").Key>) => void;
  /**
   * Called when an item is activated with Enter or a double-click.
   */
  onAction?: (key: import("react-aria-components").Key) => void;
}

export const treeDefaults = {
  selectionMode: "none",
} as const;

export const treeMeta = {
  "name": "Tree",
  "version": "0.1.0",
  "status": "experimental",
  "role": "tree"
} as const;

